import React, { useState, useCallback } from 'react';
import { predictImage } from '../services/api';

/**
 * ImageUpload Component
 * Handles image upload and YOLO detection display.
 * Supports drag-and-drop and click-to-upload.
 */
const ImageUpload = () => {
  const [selectedFile, setSelectedFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [selectedModel, setSelectedModel] = useState('water_contamination');
  const [confidence, setConfidence] = useState(0.25);
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [dragActive, setDragActive] = useState(false);

  const models = [
    { key: 'water_contamination', name: '💧 Water Contamination', desc: 'Detect contaminated, clean, industrial waste, sewage' },
    { key: 'algal_bloom', name: '🌿 Algal Bloom', desc: 'Detect harmful algae, green algae, red tide' },
    { key: 'fish_disease', name: '🐟 Fish Disease', desc: 'Detect bacterial, fungal infections in fish' },
    { key: 'malaria', name: '🦟 Malaria Parasite', desc: 'Detect parasitized vs uninfected cells' },
    { key: 'micro_pathogens', name: '🔬 Micro-Pathogens', desc: 'Detect E.coli, cholera, giardia' },
  ];

  const handleFileSelect = useCallback((file) => {
    if (file && file.type.startsWith('image/')) {
      setSelectedFile(file);
      setPreviewUrl(URL.createObjectURL(file));
      setResults(null);
      setError(null);
    } else {
      setError('Please select a valid image file (JPG, PNG, etc.)');
    }
  }, []);

  const handleDrop = useCallback((e) => {
    e.preventDefault();
    setDragActive(false);
    const file = e.dataTransfer.files[0];
    handleFileSelect(file);
  }, [handleFileSelect]);

  const handleDragOver = (e) => {
    e.preventDefault();
    setDragActive(true);
  };

  const handleDragLeave = () => setDragActive(false);

  const handleAnalyze = async () => {
    if (!selectedFile) return;

    setLoading(true);
    setError(null);
    setResults(null);

    try {
      const result = await predictImage(selectedFile, selectedModel, confidence);
      setResults(result);
    } catch (err) {
      const msg = err.response?.data?.error || err.message || 'Detection failed';
      setError(`Detection failed: ${msg}. Make sure Flask backend is running.`);
    } finally {
      setLoading(false);
    }
  };

  const dangerousClasses = new Set([
    'contaminated', 'industrial_waste', 'sewage', 'chemical_spill',
    'parasitized', 'harmful_algae', 'bacterial_infection',
    'e_coli', 'cholera_vibrio', 'giardia'
  ]);

  return (
    <div>
      <h2 className="section-title">
        <span className="section-title__icon">🔬</span>
        Image-Based Detection
      </h2>

      <div className="grid-2">
        {/* Left: Upload & Controls */}
        <div>
          {/* Upload Zone */}
          <div
            className={`upload-zone ${dragActive ? 'upload-zone--active' : ''}`}
            onDrop={handleDrop}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onClick={() => document.getElementById('file-input').click()}
            id="upload-zone"
          >
            <input
              id="file-input"
              type="file"
              accept="image/*"
              style={{ display: 'none' }}
              onChange={(e) => handleFileSelect(e.target.files[0])}
            />
            {previewUrl ? (
              <img
                src={previewUrl}
                alt="Selected"
                style={{
                  maxWidth: '100%',
                  maxHeight: '300px',
                  borderRadius: 'var(--radius-md)',
                  objectFit: 'contain',
                }}
              />
            ) : (
              <>
                <div className="upload-zone__icon">📷</div>
                <div className="upload-zone__text">
                  Drag & drop an image here, or click to browse
                </div>
                <div className="upload-zone__hint">
                  Supports: JPG, PNG, BMP, WebP (max 16MB)
                </div>
              </>
            )}
          </div>

          {/* Controls */}
          <div style={{ marginTop: '1rem' }}>
            {/* Model Selection */}
            <div className="input-group" style={{ marginBottom: '1rem' }}>
              <label className="input-group__label">Detection Model</label>
              <select
                className="select"
                value={selectedModel}
                onChange={(e) => setSelectedModel(e.target.value)}
                style={{ width: '100%' }}
                id="model-select"
              >
                {models.map(m => (
                  <option key={m.key} value={m.key}>{m.name}</option>
                ))}
              </select>
              <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: 4 }}>
                {models.find(m => m.key === selectedModel)?.desc}
              </span>
            </div>

            {/* Confidence Threshold */}
            <div className="input-group" style={{ marginBottom: '1rem' }}>
              <label className="input-group__label">
                Confidence Threshold: {(confidence * 100).toFixed(0)}%
              </label>
              <input
                type="range"
                min="0.1"
                max="0.9"
                step="0.05"
                value={confidence}
                onChange={(e) => setConfidence(parseFloat(e.target.value))}
                style={{ width: '100%', accentColor: 'var(--accent-blue)' }}
                id="confidence-slider"
              />
            </div>

            {/* Analyze Button */}
            <button
              className="btn btn--primary btn--lg"
              style={{ width: '100%' }}
              onClick={handleAnalyze}
              disabled={!selectedFile || loading}
              id="analyze-btn"
            >
              {loading ? (
                <><span className="spinner" style={{ width: 20, height: 20, margin: 0, borderWidth: 2 }} /> Analyzing...</>
              ) : (
                '🔍 Analyze Image'
              )}
            </button>
          </div>

          {error && (
            <div className="alert-banner alert-banner--danger" style={{ marginTop: '1rem' }}>
              <span>❌</span>
              <span>{error}</span>
            </div>
          )}
        </div>

        {/* Right: Results */}
        <div>
          {results ? (
            <div className="card fade-in">
              <div className="card__title">
                📋 Detection Results — {results.model_name}
              </div>

              {/* Summary */}
              <div style={{ display: 'flex', gap: 16, marginBottom: '1rem', flexWrap: 'wrap' }}>
                <div className="stat-card" style={{ flex: 1, minWidth: 120 }}>
                  <span className="stat-card__label">Detections</span>
                  <span className="stat-card__value" style={{ color: 'var(--accent-blue)', fontSize: '1.5rem' }}>
                    {results.total_detections}
                  </span>
                </div>
                <div className="stat-card" style={{ flex: 1, minWidth: 120 }}>
                  <span className="stat-card__label">Status</span>
                  <span className={`risk-badge risk-badge--${results.is_dangerous ? 'high' : 'low'}`}>
                    {results.is_dangerous ? '⚠️ DANGEROUS' : '✅ SAFE'}
                  </span>
                </div>
              </div>

              {/* Detection List */}
              {results.detections.length > 0 ? (
                <div>
                  <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginBottom: 8 }}>
                    Detected Objects:
                  </div>
                  {results.detections.map((det, idx) => (
                    <div
                      key={idx}
                      className={`detection-item ${dangerousClasses.has(det.class) ? 'detection-item--danger' : ''}`}
                    >
                      <div>
                        <span className="detection-item__class">
                          {det.class.replace(/_/g, ' ')}
                        </span>
                        <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>
                          Class ID: {det.class_id}
                        </div>
                      </div>
                      <div style={{ textAlign: 'right' }}>
                        <div className="detection-item__confidence">
                          {(det.confidence * 100).toFixed(1)}%
                        </div>
                        <div className="progress" style={{ width: 80, marginTop: 4 }}>
                          <div
                            className={`progress__bar ${det.confidence > 0.7 ? 'progress__bar--green' : det.confidence > 0.4 ? 'progress__bar--orange' : 'progress__bar--red'}`}
                            style={{ width: `${det.confidence * 100}%` }}
                          />
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div style={{ textAlign: 'center', padding: '2rem', color: 'var(--text-muted)' }}>
                  No objects detected above {(confidence * 100).toFixed(0)}% confidence.
                  <br />Try lowering the confidence threshold.
                </div>
              )}

              {/* Alert info */}
              {results.alert && (
                <div className="alert-banner alert-banner--danger" style={{ marginTop: '1rem' }}>
                  <span>🚨</span>
                  <span>Alert Triggered: {results.alert.alert_id}</span>
                </div>
              )}

              {/* Timestamp */}
              <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: '1rem', textAlign: 'right' }}>
                Analyzed at: {new Date(results.timestamp).toLocaleString()}
              </div>
            </div>
          ) : (
            <div className="card" style={{ textAlign: 'center', padding: '4rem 2rem' }}>
              <div style={{ fontSize: '4rem', marginBottom: '1rem', opacity: 0.3 }}>🔬</div>
              <div style={{ color: 'var(--text-muted)', fontSize: '1rem' }}>
                Upload an image and click Analyze to see detection results
              </div>
              <div style={{ color: 'var(--text-muted)', fontSize: '0.8rem', marginTop: '0.5rem' }}>
                Supports water samples, microscope slides, fish images, satellite imagery
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ImageUpload;
